from collections import deque, defaultdict

def read_ints():
    return list(map(int, input().split()))

n, k = read_ints()
main_courses = read_ints()

# Read course dependencies
course_dependencies = [[] for _ in range(n + 1)]
for i in range(1, n + 1):
    t_i = read_ints()[0]
    if t_i > 0:
        dependencies = read_ints()
        course_dependencies[i] = dependencies

# Topological sort using Kahn's algorithm
in_degree = [0] * (n + 1)
for i in range(1, n + 1):
    for dep in course_dependencies[i]:
        in_degree[dep] += 1

# Initialize queue with nodes having zero in-degree
queue = deque()
for course in main_courses:
    queue.append(course)

# List to store the order of courses
order = []

# Perform topological sort
while queue:
    course = queue.popleft()
    order.append(course)

    for dep in course_dependencies[course]:
        in_degree[dep] -= 1
        if in_degree[dep] == 0:
            queue.append(dep)

# Check if there was a cycle (i.e., not all courses were included in the order)
if len(order) != n:
    print(-1)
else:
    print(len(order))
    print(' '.join(map(str, order)))
